def get_master_120_period_py(
    language: str,
    level: str,
    day_number: int,
    custom_topic: Optional[str] = None
) -> Dict[str, Any]:
    """
    Returns guaranteed unique, non-repeating period data for Days 1 to 120+.
    """
    lang_lower = (language or "english").lower().strip()
    is_french = "french" in lang_lower or "français" in lang_lower
    base_list = MASTER_120_FRENCH if is_french else MASTER_120_ENGLISH

    if 1 <= day_number <= 120:
        entry = dict(base_list[day_number - 1])
        if custom_topic and len(custom_topic.strip()) > 3 and not any(k in custom_topic.lower() for k in ["complete", "course", "curriculum", "blueprint"]):
            c_clean = custom_topic.strip()
            if day_number == 1:
                entry["topic"] = f"{c_clean} : Foundations & Principles"
            else:
                entry["topic"] = f"{c_clean} — Part {day_number}: {entry['topic']}"
            entry["grammar_rule"] = f"{entry['grammar_rule']} (Applied to {c_clean})"
        return entry

    # Beyond 120
    ext = day_number - 120
    return {
        "day_number": day_number,
        "module_number": 12,
        "module_title": "Module 12: Advanced Specialized Extension & Capstone Research",
        "topic": f"Specialized Research Seminar {day_number}: Advanced Academic Mastery (Part {ext})",
        "grammar_rule": f"Advanced discourse synthesis and stylistic refinement (Phase {ext})",
        "objective": f"Achieve autonomous professional fluency in {language} at international certification standard.",
        "vocab": [
            {"word": f"Specialized Term {day_number}A", "meaning": f"Domain concept {ext}", "pronunciation": f"/term-{day_number}/", "example_sentence": f"Applying specialized term {day_number}."}
        ],
        "dialogue": [
            f"Professor: 'Welcome to Seminar {day_number}. Let us review Phase {ext}.'",
            f"Researcher: 'We have compiled the synthesis for today\'s defense.'"
        ],
        "drills": [
            {"question": f"Analyze Phase {ext} research findings.", "answer": "Rigorous academic synthesis.", "explanation": "Advanced competence benchmark."}
        ]
    }
